{
  "claims": [
    {
      "claim": "Large Language Models (LLMs) are susceptible to prompt injection attacks, despite claims from proposed defenses that they successfully mitigate these attacks.",
      "source_id": "3ce4ffcf18e73d27",
      "evidence_quote": "Large Language Models (LLMs) are vulnerable to prompt injection attacks, and several defenses have recently been proposed, often claiming to mitigate these attacks successfully.",
      "confidence": 0.9
    },
    {
      "claim": "Existing studies on prompt injection defenses lack a principled evaluation approach.",
      "source_id": "3ce4ffcf18e73d27",
      "evidence_quote": "However, we argue that existing studies lack a principled approach to evaluating these defenses.",
      "confidence": 0.8
    },
    {
      "claim": "Prior studies have not followed a comprehensive evaluation methodology for assessing defenses against prompt injection attacks.",
      "source_id": "3ce4ffcf18e73d27",
      "evidence_quote": "Our critical evaluation reveals that prior studies have not followed such a comprehensive evaluation methodology.",
      "confidence": 0.85
    },
    {
      "claim": "Without the proposed Adversarial Fine-Tuning defense, prompt injection and goal hijacking attacks succeeded 31% of the time on GPT-3 series models.",
      "source_id": "0a92d83e827d00be",
      "evidence_quote": "Our results show that, without this defense, the attacks succeeded 31% of the time on GPT-3 series models.",
      "confidence": 0.9
    },
    {
      "claim": "A prompt injection attack aims to inject malicious instructions or data into an LLM-Integrated Application's input to make it produce results desired by an attacker.",
      "source_id": "13ae121641712ce1",
      "evidence_quote": "A prompt injection attack aims to inject malicious instruction/data into the input of an LLM-Integrated Application such that it produces results as an attacker desires.",
      "confidence": 0.9
    },
    {
      "claim": "Existing works on prompt injection attacks and defenses are limited to case studies, leading to a lack of systematic understanding in the literature.",
      "source_id": "13ae121641712ce1",
      "evidence_quote": "Existing works are limited to case studies. As a result, the literature lacks a systematic understanding of prompt injection attacks and their defenses.",
      "confidence": 0.85
    },
    {
      "claim": "The research presents a comprehensive examination of prompt-to-SQL (P2SQL) injections targeting web applications built on the Langchain framework.",
      "source_id": "e4a84cae69e7b85f",
      "evidence_quote": "In this paper, we present a comprehensive examination of prompt-to-SQL (P$_2$SQL) injections targeting web applications based on the Langchain framework.",
      "confidence": 0.9
    },
    {
      "claim": "The PromptGuard framework enhances robustness across multiple LLMs, achieving up to a 67% reduction in injection success rate and an F1-score of 0.91 in detection, with a latency increase below 8%.",
      "source_id": "260f35daa2852dc6",
      "evidence_quote": "Evaluations on PromptBench, InjectBench, and TruthfulQA demonstrate that the framework enhances robustness across multiple LLMs, achieving up to a 67% reduction in injection success rate and an F1-score of 0.91 in detection, with a latency increase below 8%.",
      "confidence": 0.9
    }
  ]
}

